def coerce(key, value):
    if key == 'workers':
        return int(value)
    if key == 'debug':
        if isinstance(value, str):
            return value.strip().lower() in ('1', 'true', 'yes', 'on')
        return bool(value)
    return value

from .defaults import DEFAULTS
from .coerce import coerce

def load_config(file_values, environ):
    result = dict(DEFAULTS)          # start from defaults
    result.update(file_values)       # file values override defaults
    for key in DEFAULTS:
        env_key = 'APP_' + key.upper()
        if env_key in environ:
            result[key] = coerce(key, environ[env_key])  # env overrides all
    return result
